function text(value, fallback = '') {
  if (value === null || value === undefined) {
    return fallback;
  }

  return String(value);
}

function truncate(value, maxLength) {
  const source = text(value);

  if (source.length <= maxLength) {
    return source;
  }

  return `${source.slice(0, maxLength)}\n...[truncated]`;
}

const incident = $json;

const fingerprintLabel =
  `autofix-fp-${incident.fingerprint}`;

const endpoint = [
  incident.sample_http_method,
  incident.sample_request_path,
]
  .filter(Boolean)
  .join(' ');

const rawSummary = [
  '[AutoFix]',
  `[${incident.service_name}]`,
  incident.exception_type,
  endpoint ? `at ${endpoint}` : '',
]
  .filter(Boolean)
  .join(' ');

const summary = truncate(rawSummary, 240);

// Stage 6: stack trace embedded in the machine-readable block is capped
// at 12000 characters (Stage 6 Section 21) -- separate from (and may
// differ slightly in truncation point from) the human-readable copy
// below, but both share the same 12000-character limit.
const MAX_STACK_TRACE_LENGTH = 12000;
const truncatedStackTrace = truncate(incident.sample_stack_trace, MAX_STACK_TRACE_LENGTH);

// Stage 6: machine-readable context consumed by n8n Workflow 05
// ("Get AutoFix Ticket Context"). This -- not any PostgreSQL
// snapshot -- becomes the Copilot prompt's source of task detail, so it
// must be self-contained and carry enough to independently confirm it
// still matches the claimed incident (incidentId + fingerprint).
const autofixContext = {
  schemaVersion: 1,
  incidentId: incident.id,
  fingerprint: incident.fingerprint,
  service: incident.service_name,
  environment: incident.environment,
  exceptionType: incident.exception_type,
  normalizedMessage: text(incident.normalized_exception_message, 'n/a'),
  applicationFrame: text(incident.application_stack_frame, 'n/a'),
  httpMethod: text(incident.sample_http_method, 'n/a'),
  requestPath: text(incident.sample_request_path, 'n/a'),
  occurrenceCount: incident.occurrence_count,
  firstSeenAt: incident.first_seen_at,
  lastSeenAt: incident.last_seen_at,
  sampleCorrelationId: text(incident.sample_correlation_id, 'n/a'),
  stackTrace: truncatedStackTrace,
};

const description = [
  // Human-readable section (Stage 6 Section 5.2) -- always present
  // alongside the machine-readable block below, never instead of it.
  'Automatically detected application incident.',
  '',
  `Service: ${incident.service_name}`,
  `Environment: ${incident.environment}`,
  `Exception: ${incident.exception_type}`,
  `Endpoint: ${endpoint}`,
  `Occurrences: ${incident.occurrence_count}`,
  '',
  'This ticket is eligible for automated analysis.',
  'Any generated change requires human review.',
  '',
  'AutoFix policy:',
  '- This issue was generated automatically.',
  '- Any generated fix must include a regression test.',
  '- Direct push and automatic merge are prohibited.',
  '',
  // Machine-readable section (Stage 6 Section 5.1). n8n Workflow 05
  // parses this fenced block by its literal marker lines -- do not
  // rename AUTOFIX_CONTEXT_V1 / AUTOFIX_CONTEXT_END without also
  // updating that workflow's parsing Code node.
  'AUTOFIX_CONTEXT_V1',
  '```json',
  JSON.stringify(autofixContext, null, 2),
  '```',
  'AUTOFIX_CONTEXT_END',
].join('\n');

return {
  json: {
    ...incident,
    fingerprintLabel,
    summary,
    description,
    jiraLabels: [
      'autofix-poc',
      'auto-generated',
      'autofix-candidate',
      fingerprintLabel,
    ],
  },
};
